.diff-lines { max-height: 280px; overflow: auto; font-family: Consolas, monospace; font-size: 0.8rem; background: var(--bg-secondary); border: 1px solid var(--border); border-radius: var(--radius-md); padding: 8px; }
.diff-line-add { color: #6ecf8a; }
