.timer-outcome-btns { display: flex; flex-direction: column; gap: 8px; margin: 12px 0; }

/* ---- Task Card System ---- */
.task-card {
  --card-bg: #1a2038; --card-accent: #f0c040; --card-border: rgba(240,192,64,0.35);
  --card-pattern: rgba(255,255,255,0.04); --card-glow: rgba(240,192,64,0.45);
  --card-text: #f0e8da; --card-muted: #8a8298;
  position: relative; border-radius: 16px; border: 2px solid var(--card-border); background: var(--card-bg);
  color: var(--card-text); padding: 0; overflow: hidden; transition: border-color 0.2s, box-shadow 0.2s;
  box-shadow: 0 6px 22px rgba(0,0,0,0.4), inset 0 0 0 1px rgba(255,255,255,0.05);
  animation: cardIn 0.45s both; width: 100%;
}
.task-card::before { content: ''; position: absolute; inset: 10px; border: 1px solid rgba(255,255,255,0.09); border-radius: 11px; pointer-events: none; z-index: 0; }
.task-card::after { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 38%; background: linear-gradient(180deg, rgba(255,255,255,0.06), transparent); pointer-events: none; z-index: 0; }
.task-card-ornament { position: absolute; width: 14px; height: 14px; border: 2px solid var(--card-accent); opacity: 0.55; z-index: 2; pointer-events: none; }
.task-card-ornament.tl { top: 5px; left: 5px; border-right: 0; border-bottom: 0; border-radius: 4px 0 0 0; }
.task-card-ornament.tr { top: 5px; right: 5px; border-left: 0; border-bottom: 0; border-radius: 0 4px 0 0; }
.task-card-ornament.bl { bottom: 5px; left: 5px; border-right: 0; border-top: 0; border-radius: 0 0 0 4px; }
.task-card-ornament.br { bottom: 5px; right: 5px; border-left: 0; border-top: 0; border-radius: 0 0 4px 0; }
.task-card-header {
  display: flex; align-items: flex-start; justify-content: space-between; gap: 8px;
  padding: 12px 14px 8px; position: relative; z-index: 1;
  border-bottom: 1px solid rgba(255,255,255,0.06); background: linear-gradient(180deg, rgba(0,0,0,0.18), transparent);
}
.task-card-header-main { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; min-width: 0; }
.task-card-corner {
  font-size: 0.68rem; letter-spacing: 0.5px; padding: 3px 9px; border-radius: 8px;
  background: rgba(0,0,0,0.28); border: 1px solid var(--card-border); color: var(--card-accent);
  font-family: var(--font-heading); white-space: nowrap;
}
.task-card-mark {
  min-width: 26px; height: 26px; padding: 0 6px; border-radius: 13px; border: 1px solid var(--card-border);
  background: rgba(0,0,0,0.25); font-size: 0.68rem; display: inline-flex; align-items: center; justify-content: center;
  color: var(--card-accent); font-family: var(--font-heading); flex-shrink: 0;
}
.task-card-body-zone { position: relative; padding: 10px 14px 8px; z-index: 1; min-height: 88px; }
.task-card-title { font-family: var(--font-heading); font-size: 1.08rem; margin: 0 0 6px; line-height: 1.35; color: var(--card-text); font-weight: 600; }
.task-card-desc { font-size: 0.86rem; color: var(--card-muted); line-height: 1.5; max-height: 3em; overflow: hidden; margin-bottom: 8px; }
.task-card-meta { display: flex; flex-wrap: wrap; gap: 6px 10px; margin-bottom: 8px; }
.task-card-stat {
  display: inline-flex; align-items: center; gap: 4px; font-size: 0.78rem; color: var(--card-muted);
  padding: 2px 8px; border-radius: 8px; background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.06);
}
.task-card-stat i { color: var(--card-accent); font-size: 0.72rem; opacity: 0.85; }
.task-card-stat.stat-priority { color: var(--card-accent); border-color: rgba(255,255,255,0.1); }
.task-card-pattern { position: absolute; inset: 28px 10px 10px; display: flex; align-items: center; justify-content: center; z-index: 0; opacity: 0.5; pointer-events: none; }
.task-card-pattern > span { font-family: var(--font-display); font-size: 2.8rem; color: var(--card-accent); opacity: 0.18; text-shadow: 0 0 24px var(--card-glow); }
.task-card-pattern.lang-pattern { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 5px 8px; align-content: center; padding: 8px; inset: 24px 12px 8px; opacity: 0.32; }
.lang-word { font-family: var(--font-body); font-size: 0.68rem; text-transform: lowercase; letter-spacing: 0.3px; padding: 3px 5px; border-radius: 5px; border: 1px solid rgba(143,212,160,0.18); background: rgba(143,212,160,0.05); color: rgba(143,212,160,0.75); text-align: center; }
.task-card-tags { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 4px; position: relative; z-index: 1; }
.task-card-tags .badge { font-size: 0.72rem; padding: 2px 8px; }
.task-card-footer {
  padding: 8px 12px 12px; border-top: 1px solid rgba(255,255,255,0.07);
  background: linear-gradient(0deg, rgba(0,0,0,0.22), transparent); position: relative; z-index: 1;
}
.task-card-actions { display: flex; gap: 5px; flex-wrap: wrap; }
.task-card-actions .btn { padding: 5px 10px; font-size: 0.76rem; border-radius: 8px; min-height: 30px; }
.task-card-actions .btn.card-act-btn { border-color: rgba(255,255,255,0.12); background: rgba(0,0,0,0.25); }
.task-card-actions .btn.card-act-btn.pri { background: linear-gradient(135deg, rgba(201,159,46,0.85), rgba(240,192,64,0.95)); color: #0a0e1a; border: 0; font-weight: 600; }
.task-card-actions .btn.card-act-btn.danger { background: rgba(231,76,60,0.12); border-color: rgba(231,76,60,0.45); }
.task-card-actions .btn.card-act-btn:hover { border-color: var(--card-accent); transform: translateY(-1px); }
.task-card.status-completed { opacity: 0.72; filter: saturate(0.85); }
.task-card.status-discarded { opacity: 0.65; filter: grayscale(0.35); }
.task-card.status-blocked { border-color: rgba(155,89,182,0.45); }

/* Theme variants */
.task-card.theme-math { --card-bg: linear-gradient(145deg, #121a32, #1a2848); --card-accent: #6eb5ff; --card-border: rgba(110,181,255,0.42); --card-glow: rgba(110,181,255,0.5); background: var(--card-bg); }
.task-card.theme-math::before { background-image: repeating-linear-gradient(0deg, transparent, transparent 11px, rgba(110,181,255,0.06) 11px, rgba(110,181,255,0.06) 12px), repeating-linear-gradient(90deg, transparent, transparent 11px, rgba(110,181,255,0.06) 11px, rgba(110,181,255,0.06) 12px); }
.task-card.theme-lang { --card-bg: linear-gradient(145deg, #142018, #1a3024); --card-accent: #8fd4a0; --card-border: rgba(143,212,160,0.42); --card-glow: rgba(240,200,100,0.35); background: var(--card-bg); }
.task-card.theme-history { --card-bg: linear-gradient(145deg, #241a12, #322418); --card-accent: #d4a574; --card-border: rgba(212,165,116,0.4); --card-glow: rgba(180,80,60,0.25); background: var(--card-bg); }
.task-card.theme-code { --card-bg: linear-gradient(145deg, #0e1418, #152028); --card-accent: #4ecdc4; --card-border: rgba(78,205,196,0.35); --card-glow: rgba(78,205,196,0.4); background: var(--card-bg); }
.task-card.theme-write { --card-bg: linear-gradient(145deg, #1e1828, #2a2238); --card-accent: #c9b8e8; --card-border: rgba(201,184,232,0.35); --card-glow: rgba(201,184,232,0.3); background: var(--card-bg); }
.task-card.theme-science { --card-bg: linear-gradient(145deg, #121828, #1a2240); --card-accent: #7eb8ff; --card-border: rgba(126,184,255,0.35); --card-glow: rgba(155,89,182,0.35); background: var(--card-bg); }
.task-card.theme-review { --card-bg: linear-gradient(145deg, #221c14, #2e2618); --card-accent: #f0c878; --card-border: rgba(240,200,120,0.35); --card-glow: rgba(240,200,120,0.35); background: var(--card-bg); }
.task-card.theme-default { --card-bg: linear-gradient(145deg, #181c28, #222838); --card-accent: #f0c040; --card-border: rgba(240,192,64,0.28); background: var(--card-bg); }

/* Drawn card flip system */
.task-card.drawn-card { margin-top: 12px; perspective: 900px; width: calc(100% * var(--card-scale, 1)); max-width: 420px; margin-left: auto; margin-right: auto; }
.task-card.drawn-card.urgent { --card-border: rgba(231,76,60,0.55); box-shadow: 0 0 24px rgba(231,76,60,0.25); }
.task-card-inner { position: relative; width: 100%; aspect-ratio: 3.5 / 2.2; transform-style: preserve-3d; transition: transform 0.65s cubic-bezier(0.4, 0.2, 0.2, 1); }
.task-card.is-revealing .task-card-inner { transform: rotateY(180deg); }
.task-card-face { position: absolute; inset: 0; backface-visibility: hidden; -webkit-backface-visibility: hidden; border-radius: 14px; overflow: hidden; width: 100%; height: 100%; }
.task-card-back { background: linear-gradient(135deg, #1a2240, #0f1422); border: 2px solid rgba(240,192,64,0.35); border-radius: 16px; display: flex; align-items: center; justify-content: center; transform: rotateY(0); }
.task-card-back .card-back-emblem { width: 72px; height: 72px; border-radius: 50%; border: 2px solid rgba(240,192,64,0.5); display: flex; align-items: center; justify-content: center; font-family: var(--font-display); font-size: 1.6rem; color: var(--gold); box-shadow: inset 0 0 20px rgba(240,192,64,0.15); background: radial-gradient(circle, rgba(240,192,64,0.12), transparent); }
.task-card-back .card-back-pattern { position: absolute; inset: 12px; border-radius: 10px; background: repeating-linear-gradient(45deg, rgba(240,192,64,0.06) 0 6px, transparent 6px 12px), repeating-linear-gradient(-45deg, rgba(255,255,255,0.03) 0 8px, transparent 8px 16px); }
/* Drawn card flip system - 横向（landscape） */
.task-card.drawn-card { margin-top: 8px; perspective: 900px; width: calc(min(500px, 90vw) * var(--card-scale, 1)); max-width: 500px; margin-left: auto; margin-right: auto; }
.task-card.drawn-card.urgent { --card-border: rgba(231,76,60,0.55); box-shadow: 0 0 24px rgba(231,76,60,0.25); }
.task-card-inner { position: relative; width: 100%; aspect-ratio: 5 / 3; transform-style: preserve-3d; transition: transform 0.65s cubic-bezier(0.4, 0.2, 0.2, 1); }
.task-card.is-revealing .task-card-inner { transform: rotateY(180deg); }
.task-card-face { position: absolute; inset: 0; backface-visibility: hidden; -webkit-backface-visibility: hidden; border-radius: 14px; overflow: hidden; width: 100%; height: 100%; }
.task-card-back { background: linear-gradient(135deg, #1a2240, #0f1422); border: 2px solid rgba(240,192,64,0.35); border-radius: 16px; display: flex; align-items: center; justify-content: center; transform: rotateY(0); }
.task-card-back .card-back-emblem { width: 64px; height: 64px; border-radius: 50%; border: 2px solid rgba(240,192,64,0.5); display: flex; align-items: center; justify-content: center; font-family: var(--font-display); font-size: 1.4rem; color: var(--gold); box-shadow: inset 0 0 20px rgba(240,192,64,0.15); background: radial-gradient(circle, rgba(240,192,64,0.12), transparent); }
.task-card-back .card-back-pattern { position: absolute; inset: 12px; border-radius: 10px; background: repeating-linear-gradient(45deg, rgba(240,192,64,0.06) 0 6px, transparent 6px 12px), repeating-linear-gradient(-45deg, rgba(255,255,255,0.03) 0 8px, transparent 8px 16px); }
.task-card-front { transform: rotateY(180deg); background: var(--card-bg); border-radius: 16px; display: flex; flex-direction: row; height: 100%; }
/* 横向布局：左侧任务信息，右侧操作按钮 */
.task-card-front .task-card-header { width: auto; flex: 1.5; border-bottom: none; border-right: 1px solid rgba(255,255,255,0.06); padding: 8px 10px; display: flex; flex-direction: column; justify-content: center; }
.task-card-front .task-card-body-zone { width: auto; flex: 2; padding: 8px 10px; display: flex; flex-direction: column; justify-content: center; min-height: 0; }
.task-card-front .task-card-footer { width: auto; flex: 1; padding: 8px; border-top: none; border-left: 1px solid rgba(255,255,255,0.06); background: transparent; display: flex; flex-direction: column; justify-content: center; }
.drawn-card-stage { display: flex; justify-content: center; perspective: 900px; width: 100%; }

/* Animations */
.task-card.is-drawing { animation: cardDrawOut 0.6s ease-out both; }
.task-card.is-completing { animation: cardCompleteGlow 0.65s ease-out both; }
.task-card.is-evaporating, .task-card.is-fly-to-pile { animation: cardEvaporate 0.65s ease-in forwards; pointer-events: none; }
.task-card.is-discarding { animation: cardDiscardFly 0.65s ease-in forwards; pointer-events: none; }
.task-card.is-skipping { animation: cardSkipAway 0.55s ease-in forwards; pointer-events: none; }
.task-card.is-refusing { animation: cardRefuseAway 0.55s ease-in forwards; pointer-events: none; }
.task-card.is-burning { animation: cardBurn 0.9s ease-in forwards; pointer-events: none; }

@keyframes deckBreath { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-6px); } }
@keyframes deckPop { 0% { transform: translate(12px, -20px) rotate(-4deg); } 100% { transform: translate(24px, -48px) rotate(-8deg) scale(1.05); opacity: 0.3; } }
@keyframes cardDrawOut { 0% { opacity: 0; transform: translateY(40px) scale(0.88) rotate(-3deg); } 100% { opacity: 1; transform: translateY(0) scale(1) rotate(0); } }
@keyframes cardCompleteGlow { 0% { filter: brightness(1); } 35% { filter: brightness(1.25); box-shadow: 0 0 28px var(--card-glow); } 100% { filter: brightness(1.05); } }
@keyframes cardEvaporate { 0% { opacity: 1; transform: scale(1); } 40% { opacity: 1; transform: scale(1.02); } 100% { opacity: 0; transform: scale(0.65) translate(70px, -50px); filter: blur(1px); } }
@keyframes cardDiscardFly { 0% { opacity: 1; transform: translate(0, 0) rotate(0); } 100% { opacity: 0.25; transform: translate(200px, 80px) rotate(12deg) scale(0.82); filter: grayscale(0.7) saturate(0.5); } }
@keyframes cardSkipAway { to { opacity: 0; transform: translateX(-110px) rotate(-8deg); } }
@keyframes cardRefuseAway { to { opacity: 0; transform: translateX(-70px) scale(0.9) rotate(-4deg); filter: brightness(0.55); } }
@keyframes cardBurn { 0% { opacity: 1; transform: scale(1); filter: brightness(1); } 30% { filter: brightness(1.3) hue-rotate(-10deg); } 60% { filter: brightness(1.5) hue-rotate(-20deg); transform: scale(1.03); } 100% { opacity: 0; transform: scale(0.1); filter: brightness(2) hue-rotate(-30deg); border-radius: 50%; } }

/* Flying card animation overlay */
.card-fly-layer { position: fixed; top: 0; left: 0; right: 0; bottom: 0; pointer-events: none; z-index: 500; }
.card-fly-layer .flying-card {
  position: absolute; width: 250px; height: 150px; /* 横向比例 5:3 */
  border-radius: 12px; border: 2px solid rgba(240,192,64,0.35);
  background: linear-gradient(135deg, #222a48, #141a30);
  box-shadow: 0 8px 32px rgba(0,0,0,0.6); transform-origin: center center;
}

/* Stats bar - 缩小到角落 */
.gacha-stats-bar { font-size: 0.72rem; color: var(--text-muted); margin-top: 8px; display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; opacity: 0.7; }
.gacha-stats-bar span { display: flex; align-items: center; gap: 4px; }
.gacha-stats-bar strong { color: var(--gold); font-weight: 600; }

/* Card size control - 位置微调 */
.card-size-control { position: absolute; right: 20px; bottom: 4px; display: flex; align-items: center; gap: 6px; z-index: 5; opacity: 0.6; transition: opacity 0.2s; }
.card-size-control:hover { opacity: 1; }
.card-size-control label { font-size: 0.68rem; color: var(--text-muted); white-space: nowrap; }
.card-size-control input[type=range] { width: 70px; accent-color: var(--gold); }

/* Drawn card scale 应用 */
.drawn-card-stage { display: flex; justify-content: center; perspective: 900px; width: 100%; transform: scale(var(--card-scale, 1)); transform-origin: center center; }

/* 抽卡标签选择行 */
.gacha-tag-row { display: flex; align-items: center; justify-content: center; gap: 8px; margin: 12px 0 0; }

/* 抽卡控件行 */
.gacha-controls-row { display: flex; align-items: center; justify-content: center; gap: 24px; margin: 12px 0 0; flex-wrap: wrap; }
.gacha-time-row { display: flex; align-items: center; gap: 6px; }

/* Multi-draw controls */
.gacha-multi-row { display: flex; align-items: center; gap: 12px; justify-content: center; margin-top: 8px; flex-wrap: wrap; }
.gacha-multi-row.hidden { display: none !important; }
.gacha-multi-btn {
  background: linear-gradient(135deg, rgba(201,159,46,0.85), rgba(240,192,64,0.95));
  color: #0a0e1a; border: 0; font-weight: 700; padding: 8px 16px;
  border-radius: var(--radius-md); cursor: pointer; font-family: var(--font-body);
  font-size: 0.9rem; transition: 0.2s; display: inline-flex; align-items: center; gap: 6px;
}
.gacha-multi-btn:hover { box-shadow: 0 0 16px rgba(240,192,64,0.35); }
.gacha-multi-btn:disabled { opacity: 0.45; cursor: not-allowed; transform: none !important; }
.gacha-multi-count-wrap { display: flex; align-items: center; gap: 6px; }
.gacha-multi-count-wrap label { font-size: 0.85rem; color: var(--text-secondary); white-space: nowrap; }
.gacha-multi-count-wrap select {
  background: var(--bg-secondary); color: var(--text-primary); border: 1px solid var(--border);
  border-radius: var(--radius-md); padding: 7px 10px; font-family: var(--font-body);
  font-size: 0.9rem; cursor: pointer; min-width: 70px;
}

/* Multi-draw result area */
.gacha-multi-result { margin-top: 12px; }
.gacha-multi-result.hidden { display: none !important; }
.gacha-multi-summary {
  background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-md);
  padding: 10px 14px; margin-bottom: 10px; font-size: 0.85rem; color: var(--text-secondary);
  backdrop-filter: blur(10px); display: flex; gap: 16px; flex-wrap: wrap; justify-content: center;
}
.gacha-multi-summary strong { color: var(--gold); }
.gacha-multi-list {
  display: flex; flex-wrap: wrap; gap: 8px; justify-content: center;
}
/* 原生 <button type="button"> 样式化（与旧 div 外观对齐，新增键盘焦点环） */
button.gacha-multi-item,
.gacha-multi-item {
  background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-md);
  padding: 8px 12px; cursor: pointer; transition: 0.2s; min-width: 140px; max-width: 200px;
  backdrop-filter: blur(10px);
  /* 关键：原生 button 默认继承 button font/line-height，重置为卡片文本 */
  font-family: var(--font-body); color: var(--text-primary);
  text-align: left; display: flex; flex-direction: column; gap: 4px;
}
button.gacha-multi-item:hover,
.gacha-multi-item:hover { border-color: var(--gold); background: rgba(240,192,64,0.08); }
button.gacha-multi-item:focus-visible,
.gacha-multi-item:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
button.gacha-multi-item[aria-pressed="true"],
.gacha-multi-item.activated { border-color: var(--gold); background: rgba(240,192,64,0.18); }
button.gacha-multi-item:disabled,
.gacha-multi-item:disabled { opacity: 0.45; cursor: not-allowed; }
.gacha-multi-item-title {
  font-family: var(--font-heading); font-size: 0.85rem; color: var(--text-primary);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-bottom: 0;
}
.gacha-multi-item-meta { font-size: 0.72rem; color: var(--text-muted); display: flex; gap: 8px; }
.gacha-multi-item-tag {
  display: inline-block; padding: 1px 6px; border-radius: 6px;
  font-size: 0.65rem; background: rgba(240,192,64,0.15); color: var(--gold);
}

/* === Optional asset seam (LT_M1_5B) — DECORATIVE CSS LAYERS ONLY ===
 * Contract: docs/M1_5_ASSET_SEAM_CONTRACT_20261012.md (M1.5A).
 * CSS custom properties default to `none` so no static asset URL is
 * loaded. When real SVG/PNG assets arrive, wire them in via:
 *   body { --art-deck-layer: url(/static/assets/cards/deck/...); }
 *   body { --art-card-back-layer: url(...); }
 *   body { --art-discard-layer: url(...); }
 *   body { --art-dock-layer: url(...); }
 * All implementations below use INDEPENDENT ::before layers above the
 * existing CSS gradient / pattern backgrounds. They are
 * `pointer-events: none`, do not change layout, and are silently inert
 * when their var is `none` (browser interprets `background-image:
 * none` as a no-op). Existing gradients, textures, borders, focus
 * rings, dimensions, animations, z-index and timer semantics
 * (#timerDockTime textContent, #timerDockBar style.width) preserved.
 *
 * Implementation status per target hook:
 *   .card-deck-card         (--art-deck-layer)        : IMPLEMENTED (safe)
 *   .task-card-back         (--art-card-back-layer)   : IMPLEMENTED (safe)
 *   .discard-pile-visual-card (--art-discard-layer)   : IMPLEMENTED (safe)
 *   .gacha-draw-stage .timer-dock (--art-dock-layer)  : IMPLEMENTED (safe)
 *   .timer-progress-bar     (--art-progress-layer)    : NOT IMPLEMENTED.
 *     Rationale: the bar is 4px tall and IS the visible gold gradient
 *     fill that tracks #timerDockBar style.width. An overlay ::before
 *     would visually corrupt the authoritative progress fill and be
 *     confused with the live percentage. Leave to a dedicated contract
 *     that swaps the gradient, not adds a parallel layer.
 */
.card-deck-card::before {
  content: ''; position: absolute; inset: 0; border-radius: 12px;
  background-image: var(--art-deck-layer, none);
  background-size: cover; background-position: center; background-repeat: no-repeat;
  pointer-events: none; z-index: 0;
}
.task-card-back::before {
  content: ''; position: absolute; inset: 0; border-radius: 16px;
  background-image: var(--art-card-back-layer, none);
  background-size: cover; background-position: center; background-repeat: no-repeat;
  pointer-events: none; z-index: 0;
}
.discard-visual-card::before,
.discard-pile-visual-card::before {
  content: ''; position: absolute; inset: 0; border-radius: 12px;
  background-image: var(--art-discard-layer, none);
  background-size: cover; background-position: center; background-repeat: no-repeat;
  pointer-events: none; z-index: 0;
}
.gacha-draw-stage .timer-dock::before {
  content: ''; position: absolute; inset: 0; border-radius: var(--radius-lg);
  background-image: var(--art-dock-layer, none);
  background-size: cover; background-position: center; background-repeat: no-repeat;
  pointer-events: none; z-index: 0;
}
/* Defensive: keep dock text / progress / buttons above the optional layer. */
.gacha-draw-stage .timer-dock .timer-task-name,
.gacha-draw-stage .timer-dock .timer-time,
.gacha-draw-stage .timer-dock .timer-progress,
.gacha-draw-stage .timer-dock .timer-progress-bar,
.gacha-draw-stage .timer-dock .timer-dock-btns,
.gacha-draw-stage .timer-dock > * { position: relative; z-index: 1; }

/* === LT_M1_5C: visual asset seam ports (decoration only, no DOM/JS touch) ===
 * Adds 9 additional safe CSS custom property hooks. All default to
 * `none`. When real SVG/PNG assets arrive, override these vars on
 * `body` (or any container) and the decoration will appear. No
 * existing selector, animation, gradient, focus ring, timer
 * semantic, or z-index layer is changed. All ::before/::after
 * layers added here are `pointer-events: none` and use independent
 * z-index to sit either above or below the relevant content per
 * the contract. They do NOT replace the existing math ::before
 * grid (which is kept), nor the gold timer progress gradient
 * (which is kept), nor the #timerDockBar style.width writer
 * (which is kept). The flying-card and .flying-card wrapper
 * keep their transform/box-shadow/intrinsic size; only an inner
 * background layer is exposed.
 */

/* A) .task-card::after (decorative sheen overlay) — by default an
 *    additive sheen gradient, but replaceable via --art-card-front-layer.
 *    The ::before math-grid (L383) is intentionally NOT replaced.
 */
.task-card::after {
  background-image: var(--art-card-front-layer, linear-gradient(180deg, rgba(255,255,255,0.06), transparent));
}
/* Per-theme front decoration: math lang history code write science review default.
 * Math keeps its ::before grid untouched; only ::after overlay is theme-aware.
 * When no asset is provided the var falls back to the original sheen gradient. */
.task-card.theme-math    { --art-card-front-layer: var(--art-card-math-front,    linear-gradient(180deg, rgba(255,255,255,0.06), transparent)); }
.task-card.theme-lang    { --art-card-front-layer: var(--art-card-lang-front,    linear-gradient(180deg, rgba(255,255,255,0.06), transparent)); }
.task-card.theme-history { --art-card-front-layer: var(--art-card-history-front, linear-gradient(180deg, rgba(255,255,255,0.06), transparent)); }
.task-card.theme-code    { --art-card-front-layer: var(--art-card-code-front,    linear-gradient(180deg, rgba(255,255,255,0.06), transparent)); }
.task-card.theme-write   { --art-card-front-layer: var(--art-card-write-front,   linear-gradient(180deg, rgba(255,255,255,0.06), transparent)); }
.task-card.theme-science { --art-card-front-layer: var(--art-card-science-front, linear-gradient(180deg, rgba(255,255,255,0.06), transparent)); }
.task-card.theme-review  { --art-card-front-layer: var(--art-card-review-front,  linear-gradient(180deg, rgba(255,255,255,0.06), transparent)); }
.task-card.theme-default { --art-card-front-layer: var(--art-card-default-front, linear-gradient(180deg, rgba(255,255,255,0.06), transparent)); }
/* Math ::before grid is the only theme that uses ::before as pattern;
 * keep it as-is. For all other themes, expose the same overlay via
 * the new ::before layer; the existing math ::before is in theme-math block. */
.task-card:not(.theme-math)::before {
  background-image: var(--art-card-header-band, none);
  background-size: cover; background-position: center; background-repeat: no-repeat;
}
/* A2) four corners — expose a single background-image var; geometry
 *     (size, position, border) preserved. Fallback keeps current border-only style. */
.task-card-ornament { background-image: var(--art-card-ornament-layer, none); background-size: contain; background-position: center; background-repeat: no-repeat; }
/* A3) center pattern glyph / language grid — additive overlay only */
.task-card-pattern > span { background-image: var(--art-card-pattern-layer, none); -webkit-background-clip: text; background-clip: text; }
.task-card-pattern.lang-pattern { background-image: var(--art-card-pattern-layer, none); }

/* C) flying card — additive inner layer that never changes the
 *    transform / size / z-index of .flying-card. */
.flying-card::before {
  content: ''; position: absolute; inset: 0; border-radius: 12px;
  background-image: var(--art-fly-card-layer, none);
  background-size: cover; background-position: center; background-repeat: no-repeat;
  pointer-events: none; z-index: 0;
}

/* D) #timerPanel decoration. NO independent occlusion layer above
 *    the progress bar. The .timer-progress-bar gold gradient and
 *    #timerDockBar style.width are exactly preserved. */
#timerPanel { position: relative; }
#timerPanel::before {
  content: ''; position: absolute; inset: 0; border-radius: var(--radius-lg);
  background-image: var(--art-timer-panel-frame, none);
  background-size: cover; background-position: center; background-repeat: no-repeat;
  pointer-events: none; z-index: 0;
}
#timerPanel > * { position: relative; z-index: 1; }
/* D2) progress bar tick layer: scoped strictly to the actual
 *    Dock progress element (#timerDockBar). The bar is the live
 *    gold gradient fill that tracks #timerDockBar style.width.
 *    Selectors that target `.timer-progress-bar` broadly are
 *    dangerous because the canonical Dock rule
 *    `.gacha-draw-stage .timer-dock-active .timer-progress-bar`
 *    (specificity 0,3,0) must win, AND any other `.timer-progress
 *    > .timer-progress-bar` in the wider UI (e.g. future on-card
 *    timers) must NOT receive a default tick background.  By
 *    scoping to `#timerDockBar` (specificity 1,0,0) the optional
 *    tick layer is strictly opt-in and the default gold gradient
 *    is preserved exactly.
 *    The `style.width` writer on #timerDockBar still controls
 *    the live progress; ticks are painted on top within the same
 *    box via layered background-images.  The default is `none`,
 *    leaving the gold gradient as the only visible color. */
#timerDockBar {
  background-image:
    var(--art-timer-progress-tick, none),
    linear-gradient(90deg, var(--gold-dark), var(--gold));
}

/* E) modal frames: same variable across all five. ::before layer
 *    sits behind content; .modal > * and form controls are
 *    promoted to z-index 1. Range, button, focus, error text
 *    remain interactive. */
.modal { position: relative; overflow: hidden; }
.modal::before {
  content: ''; position: absolute; inset: 0; border-radius: var(--radius-lg);
  background-image: var(--art-modal-frame, none);
  background-size: cover; background-position: center; background-repeat: no-repeat;
  pointer-events: none; z-index: 0;
}
.modal > * { position: relative; z-index: 1; }

/* F) gacha-multi-item thumbnail: opt-in, non-interactive icon.
 *    Sits left of text only when explicitly enabled via
 *    `--art-multi-item-thumb-enable: 1` (or any truthy value).
 *    The native <button> remains the click target; the
 *    thumbnail is `pointer-events: none` and never steals focus
 *    or aria-pressed state.  Default state preserves the
 *    pre-M1.5C layout exactly: no left padding, no ::before
 *    visible, no border, no background-color fill. */
.gacha-multi-item { position: relative; }
.gacha-multi-item::before {
  content: var(--art-multi-item-thumb-enable, none); /* default = no thumbnail */
  position: absolute; left: 8px; top: 8px; width: 22px; height: 22px;
  border-radius: 6px; background-image: var(--art-multi-item-thumb, none);
  background-size: cover; background-position: center; background-repeat: no-repeat;
  background-color: transparent; border: 0;
  pointer-events: none; z-index: 0;
  display: var(--art-multi-item-thumb-enable, none); /* hide the whole box when off */
}
.gacha-multi-item > * { position: relative; z-index: 1; }

/* High-contrast / reduced-motion / reduced-data remain safe: every
 * `none` default means the entire layer is invisible. We do not
 * redefine any animation duration; we do not toggle `prefers-*`
 * ourselves, but every existing reduced-motion override in the
 * style block (none added here) still wins. */

/* Responsive */
@media (max-width: 900px) { .agent-ro-layout { grid-template-columns: 1fr; } }
@media (max-width: 600px) {
  .task-card-title { font-size: 1rem; }
  .task-card-actions .btn { padding: 4px 8px; font-size: 0.72rem; }
  .task-card-meta { gap: 4px; }
  .card-deck { width: 100px; height: 140px; left: 10px; top: 10px; }
  .discard-pile { right: 10px; top: 10px; }
  .discard-pile-stack, .discard-pile-empty { width: 100px; height: 140px; }
  .gacha-draw-stage { min-height: 280px; }
  .task-grid { grid-template-columns: 1fr; }
  .card-size-control { right: 10px; }
}



    /* === 自由任务面板 LT_RETENTION_FREE_TASK_MAIN_UI_MVP_20261023_Q（浏览器本地优先） === */
    #freeTaskPanel { padding: 14px 18px; }
    #freeTaskPanel > summary { cursor: pointer; display: flex; align-items: center; gap: 10px; list-style: none; }
    #freeTaskPanel > summary::-webkit-details-marker { display: none; }
    #freeTaskPanel > summary::marker { content: ''; }
    #freeTaskPanel > summary::before { content: '\25B8'; color: var(--gold); font-size: 0.9rem; }
    #freeTaskPanel[open] > summary::before { content: '\25BE'; }
    #freeTaskPanel .free-task-state { margin-left: auto; font-size: 0.8rem; color: var(--text-secondary); border: 1px solid var(--border); border-radius: 999px; padding: 2px 10px; white-space: nowrap; }
    #freeTaskPanel .free-task-body { margin-top: 14px; display: flex; flex-direction: column; gap: 14px; }
    #freeTaskPanel .free-task-note { font-size: 0.85rem; line-height: 1.6; color: var(--text-secondary); border-left: 3px solid var(--gold); padding-left: 10px; }
    #freeTaskPanel .free-task-form { display: flex; flex-wrap: wrap; gap: 12px 16px; align-items: flex-end; }
    #freeTaskPanel .free-task-field { display: flex; flex-direction: column; gap: 4px; min-width: 190px; flex: 1 1 190px; }
    #freeTaskPanel .free-task-field > label, #freeTaskPanel .free-task-field > legend { font-size: 0.82rem; color: var(--text-secondary); }
    #freeTaskPanel fieldset.free-task-field { border: 1px solid var(--border); border-radius: var(--radius-md); padding: 6px 12px 10px; }
    #freeTaskPanel .free-task-choice { display: inline-flex; align-items: center; gap: 6px; margin-right: 16px; font-size: 0.88rem; color: var(--text-primary); }
    #freeTaskPanel .free-task-actions { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
    #freeTaskPanel .free-task-error, #freeTaskPanel .free-task-storage-error { font-size: 0.85rem; color: var(--red); margin: 0; }
    #freeTaskPanel .free-task-current { border: 1px solid var(--border); border-radius: var(--radius-md); padding: 12px 14px; background: var(--bg-secondary); }
    #freeTaskPanel .free-task-current-head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
    #freeTaskPanel .free-task-current-name { font-size: 1rem; color: var(--text-primary); }
    #freeTaskPanel .free-task-remaining { font-family: var(--font-heading); font-size: 1.6rem; color: var(--gold); }
    #freeTaskPanel .free-task-meta, #freeTaskPanel .free-task-hint { font-size: 0.82rem; color: var(--text-secondary); margin-top: 4px; }
    #freeTaskPanel .free-task-notice { font-size: 0.85rem; color: var(--gold); margin-top: 6px; }
    #freeTaskPanel .free-task-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; }
    #freeTaskPanel .free-task-stat { border: 1px solid var(--border); border-radius: var(--radius-md); padding: 8px 12px; background: var(--bg-secondary); }
    #freeTaskPanel .free-task-stat .num { display: block; font-family: var(--font-heading); font-size: 1.3rem; color: var(--gold); }
    #freeTaskPanel .free-task-stat .lbl { font-size: 0.78rem; color: var(--text-secondary); }
    #freeTaskPanel .free-task-history-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; margin-bottom: 8px; }
    #freeTaskPanel .free-task-history-title { font-size: 0.9rem; color: var(--text-primary); }
    #freeTaskPanel .free-task-confirm { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; font-size: 0.85rem; color: var(--text-secondary); padding: 8px 0; }
    #freeTaskPanel .free-task-history-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
    #freeTaskPanel .free-task-history-list li { font-size: 0.83rem; color: var(--text-secondary); border-left: 2px solid var(--border); padding-left: 8px; }
    #freeTaskPanel [hidden] { display: none !important; }
    /* 自由任务本地备份（LT_RETENTION_FREE_TASK_LOCAL_BACKUP_20261023_S）：仅本机 JSON，不上传服务器 */
    #freeTaskPanel .free-task-backup { border-top: 1px solid var(--border); padding-top: 10px; }
    #freeTaskPanel .free-task-file-input { position: absolute; width: 1px; height: 1px; opacity: 0; pointer-events: none; }
    #freeTaskPanel .free-task-status { font-size: 0.85rem; color: var(--text-secondary); margin: 0; }
    #freeTaskPanel .free-task-backup .free-task-history-head { margin-bottom: 4px; }
    /* 首页入口按钮：低干扰、可发现、不引入新美术风格 */
    .free-task-shortcut-row { display: flex; justify-content: center; margin-top: 10px; }
    .free-task-shortcut-btn {
      font-size: 0.86rem; padding: 6px 14px; color: var(--text-secondary);
      background: transparent; border-style: dashed; opacity: 0.9;
    }
    .free-task-shortcut-btn:hover, .free-task-shortcut-btn:focus-visible {
      color: var(--gold); border-color: var(--gold); opacity: 1;
    }
    .free-task-shortcut-btn i { font-size: 0.8rem; }
    /* 首页「当前自由任务」只读状态条（LT_RETENTION_FREE_TASK_HOME_STATUS_20261023_T）
       复用 free-task.js 同一个 current / tick，不是第二个计时器，不写任何数据 */
    #freeTaskHomeStatus {
      display: flex; flex-wrap: wrap; justify-content: center; align-items: baseline;
      gap: 1px 6px; margin: 6px 0 0; padding: 0 6px; text-align: center;
      font-size: 0.8rem; line-height: 1.5; color: var(--text-secondary);
    }
    #freeTaskHomeStatus[hidden] { display: none !important; }
    #freeTaskHomeStatus i { font-size: 0.72rem; color: var(--gold); }
    /* 长活动名在 390px 下换行，不新增横向溢出 */
    #freeTaskHomeStatusText { overflow-wrap: anywhere; }
    #freeTaskHomeStatusClock { font-family: var(--font-heading); color: var(--gold); white-space: nowrap; }
    @media (max-width: 600px) {
      .free-task-shortcut-btn { font-size: 0.8rem; padding: 6px 10px; white-space: normal; }
      #freeTaskHomeStatus { font-size: 0.76rem; padding: 0 4px; }
    }
    @media (max-width: 600px) {
      #freeTaskPanel { padding: 12px 14px; }
      #freeTaskPanel .free-task-form { flex-direction: column; align-items: stretch; }
      #freeTaskPanel .free-task-remaining { font-size: 1.3rem; }
      #freeTaskPanel .free-task-stats { grid-template-columns: repeat(2, 1fr); }
    }
